// src/pages/og/[lang].png.ts
import type { APIRoute, GetStaticPaths } from 'astro';
import { renderCard } from '../../lib/og-card.mjs';
import { ogLocales } from '../../lib/og.mjs';
import { useTranslations } from '../../i18n/ui.mjs';

// One card per language route, generated by `astro build` — no prebuild step and
// no committed PNG. The language comes from the route, exactly as it does for
// the page it is the preview of.
export const getStaticPaths = (() => Object.keys(ogLocales).map(lang => ({ params: { lang } }))) satisfies GetStaticPaths;

export const GET: APIRoute = async ({ params }) => {
  const lang = params.lang ?? 'en';
  const t = useTranslations(lang);
  // The byline is the author's name, the same one the `<title>` in MainLayout
  // carries; the title is what the site is, from the one dictionary.
  const png = await renderCard({
    kicker: 'Matheus Rosa',
    title: t('site.title'),
  });
  return new Response(png, {
    headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=3600' },
  });
};
